import { useCallback, useEffect, useRef } from 'react'
import { cloneDeep, debounce } from 'lodash'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { useGetDraftQuoteDetails, useCreateDraftQuote, useUpdateDraftQuote, useCompleteDraftQuote } from '../../../Policy/state/hooks/usePolicyState'

const SAVE_INTERVAL_MS = 5000 // 5s

const mapDraftBody = (data, section, subSection) => {
  return {
    section: section || '',
    sub_section: subSection || '',
    data: cloneDeep(data)
  }
}

function useDraftApi ({ draftId: propDraftId, onGetDraftDetailSuccess, onSaveSuccess, onCompleteDraftSuccess }) {
  const draftIdRef = useRef(null)
  const createDraftDataRef = useRef(null)
  const shouldNavigateRef = useRef(true)

  const [{ draftQuotationsDetailsData = {} }, getDraftQuoteDetailsReq] = useGetDraftQuoteDetails()
  const [{ createDraftQuotationData = {} }, createDraftQuoteReq] = useCreateDraftQuote()
  const [{ completeDraftQuoteData }, completeDraftQuoteReq] = useCompleteDraftQuote()
  const [, updateDraftQuoteReq] = useUpdateDraftQuote()
  const [{
    draftQuotationsDetailsStatus,
    updateDraftQuotationStatus,
    createDraftQuotationStatus,
    completeDraftQuoteStatus
  }] = useErrorContextValue()
  const { resetError } = useResetError()
  const [{
    DRAFT_QUOTATIONS_DETAILS_LOADER,
    CREATE_DRAFT_QUOTATION_LOADER,
    UPDATE_DRAFT_QUOTATION_LOADER,
    COMPLETE_DRAFT_QUOTE_LOADER
  }] = useLoaderContextValue()
  const isSaveLoader = CREATE_DRAFT_QUOTATION_LOADER || UPDATE_DRAFT_QUOTATION_LOADER
  const isCompleteDraftLoader = COMPLETE_DRAFT_QUOTE_LOADER
  const isGetDraftLoader = DRAFT_QUOTATIONS_DETAILS_LOADER

  // ===== GET draft details ===== //

  useEffect(() => {
    if (propDraftId) {
      draftIdRef.current = propDraftId
    }

    // On page load: Get draft details from API
    if (draftIdRef.current) {
      getDraftQuoteDetailsReq({ draftQuoteId: draftIdRef.current })
    }
  }, [propDraftId, getDraftQuoteDetailsReq])

  useEffect(() => {
    if ((draftQuotationsDetailsStatus === 'success') && draftQuotationsDetailsData?.id) {
      onGetDraftDetailSuccess(draftQuotationsDetailsData)
      resetError(['draftQuotationsDetailsStatus'])
    }
  }, [resetError, draftQuotationsDetailsData, draftQuotationsDetailsStatus, onGetDraftDetailSuccess])

  // ===== POST create/update draft ===== //

  const handleSaveToDraft = useCallback((data, nextSection, nextSubSection, shouldNavigate = true) => {
    // Store navigation preference in separate ref
    shouldNavigateRef.current = shouldNavigate
    
    if (!draftIdRef.current) {
      createDraftQuoteReq({
        body: mapDraftBody(data, nextSection, nextSubSection)
      })
      createDraftDataRef.current = data
    } else {
      updateDraftQuoteReq({
        body: mapDraftBody(data, nextSection, nextSubSection),
        draftQuoteId: draftIdRef.current
      })
      createDraftDataRef.current = null
    }
  }, [createDraftQuoteReq, updateDraftQuoteReq])

  const debouncedSaveToDraft = debounce(handleSaveToDraft, SAVE_INTERVAL_MS)

  useEffect(() => {
    if (createDraftQuotationStatus === 'success') {
      resetError(['createDraftQuotationStatus'])

      // Save draft_id to local state
      draftIdRef.current = createDraftQuotationData.draft_id

      if (onSaveSuccess && shouldNavigateRef.current) {
        // For create flow, navigate immediately if shouldNavigate is true
        onSaveSuccess({ draftId: draftIdRef.current })
      }
    }
  }, [resetError, createDraftQuotationStatus, createDraftQuotationData, onSaveSuccess])

  useEffect(() => {
    // Handle the logic for 2 case: save on click next & on auto save
    if (updateDraftQuotationStatus === 'success') {
      resetError(['updateDraftQuotationStatus'])

      if (onSaveSuccess && shouldNavigateRef.current) {
        // Only navigate if shouldNavigate is true (default behavior for backward compatibility)
        onSaveSuccess({ draftId: draftIdRef.current })
      }
    }
  }, [resetError, updateDraftQuotationStatus, onSaveSuccess])

  // ===== POST complete draft ===== //

  const handleCompleteDraft = useCallback(() => {
    completeDraftQuoteReq({
      body: {},
      draftQuoteId: draftIdRef.current
    })
  }, [completeDraftQuoteReq])

  useEffect(() => {
    if (completeDraftQuoteStatus === 'success' && completeDraftQuoteData?.id) {
      resetError(['completeDraftQuoteStatus'])

      if (onCompleteDraftSuccess) {
        onCompleteDraftSuccess({ policyId: completeDraftQuoteData?.id })
      }
    }
  }, [resetError, completeDraftQuoteStatus, completeDraftQuoteData, onCompleteDraftSuccess])

  return {
    isGetDraftLoader,
    handleSaveToDraft,
    debouncedSaveToDraft,
    isSaveLoader,
    handleCompleteDraft,
    isCompleteDraftLoader
  }
}

export default useDraftApi
